Use lubridate to create a helper method to parse and format time variables

library(lubridate)

parse_time_label_midpoint &lt;- function(label) {
  if(is.null(label) || is.na(label)) {
    return(as.POSIXct(NA))
  }

  parts &lt;- strsplit(label, " to ")[[1]]

  if(length(parts) != 2) {
    return(as.POSIXct(NA))
  }

  start_clean &lt;- gsub("\\.","",parts[1]) #double esacping it for R syntax 
  end_clean   &lt;- gsub("\\.","",parts[2])

  start_time &lt;- lubridate::parse_date_time(start_clean, orders = "IMp")
  end_time &lt;- lubridate::parse_date_time(end_clean, orders = "IMp")

  if(is.na(start_time) || is.na(end_time)) {
    return(as.POSIXct(NA))
  }

  start_time + (end_time - start_time) / 2
}


convert_time_codes_to_midpoints &lt;- function(codes, variable_metadata) {
  result &lt;- sapply(codes, function(code) {
    if(is.na(code) || code == "") {
      return(as.POSIXct(NA))
    }

    label &lt;- variable_metadata$values$item[[code]]
    if(is.null(label)) {
      return(as.POSIXct(NA))
    }
    parse_time_label_midpoint(label)
  })
   as.POSIXct(result, origin = "1970-01-01")
}

