get_pums_data_as_tibble_numeric_vars_only_by_year_formatted &lt;- function(api_key,
                                                       year_str = c("2024", "2023", "2022", "2021"),
                                                       numeric_vars = c("AGEP", "PWGTP")) {
  pums_tibble &lt;- get_pums_data_as_tibble_numeric_vars_only_by_year(api_key, year_str, numeric_vars)

  variables_metadata &lt;- get_variables_by_year(year_str)

  for (col_name in colnames(pums_tibble)) {
    #print(variables_metadata[col_name])
    if (col_name %in% c("JWAP", "JWDP")) {
      pums_tibble[[col_name]] &lt;- convert_time_codes_to_midpoints(pums_tibble[[col_name]], variables_metadata[[col_name]])
    } else if (col_name %in% numeric_vars) {
      pums_tibble[[col_name]] &lt;- as.numeric(pums_tibble[[col_name]])
    }
  }
  pums_tibble
}

