Let’s write a helper method that helps to match a single value against a set of valid values

match_allowed_value &lt;- function(value, allowed_values) {
  for (allowed in allowed_values) {
    if (toupper(value) == toupper(allowed)) {
      return(allowed)
    }
  }
  return(NA)
}

So far we have only implemented numerical variable queries Let’s start implementing queries that include categorical variables now Also we are adding filters based on geography

get_pums_data_as_tibble_final&lt;-  function(api_key,
                                                                                   year_str = c("2024", "2023", "2022", "2021"),
                                                                                   numeric_vars = c("AGEP", "PWGTP"),
                                                                                   categorical_vars = c("SEX"),
                                                                                   geography_level = c("state"),
                                                                                   geography_value = c("37")) {
  #check for missing inputs
  if (missing(api_key)) {
    stop("apiKey are required")
  }

  year_str &lt;- match.arg(year_str, several.ok = FALSE)

  if (missing(year_str)) {
    message("year_str is not supplied, 2024 is supplied as default")
  }
  variables_supported &lt;- load_variables_rds_by_year(year_str)

  allowed_numeric_vars &lt;- c("AGEP", "GASP", "GRPIP", "JWAP", "JWDP", "JWMNP", "PWGTP")
  non_allowed_nuermic_var_in_input &lt;- FALSE
  is_pwgtp_part_of_input &lt;- FALSE
  number_of_numeric_values_outside_pwgtp &lt;- 0

  # validate the input tags
  for (v in numeric_vars) {
    if (v == "PWGTP") {
      is_pwgtp_part_of_input &lt;- TRUE
    }
    v_allowed &lt;- FALSE
    for (allowed in allowed_numeric_vars) {
      if (v == allowed) {
        v_allowed &lt;- TRUE
      }
    }

    if (!v_allowed) {
      print(v)
      non_allowed_nuermic_var_in_input &lt;- TRUE
    }
    else if (v != "PWGTP") {
      number_of_numeric_values_outside_pwgtp &lt;- number_of_numeric_values_outside_pwgtp + 1
    }
  }

  if (non_allowed_nuermic_var_in_input) {
    stop("numeric_vars must only contain: ",
         paste(allowed_numeric_vars, collapse = ", "))
  }

  if (number_of_numeric_values_outside_pwgtp == 0) {
    stop("at least one numeric var other than PWGTP must be specified in the input")
  }

  if (!is_pwgtp_part_of_input) {
    numeric_vars &lt;- c(numeric_vars, "PWGTP")
  }


  allowed_categorical_vars &lt;- c("FER", "HHL", "SCH", "SCHL", "SEX") # notice SCHL is a cat variable that can take different values
  non_allowed_categorical_var_in_input &lt;- FALSE
  numb_categorial_variables &lt;- 0
  # validate the input tags
  for (v in categorical_vars) {
    v_allowed &lt;- FALSE
    for (allowed in allowed_categorical_vars) {
      if (v == allowed) {
        v_allowed &lt;- TRUE
        numb_categorial_variables &lt;- numb_categorial_variables + 1
      }
    }

    if (!v_allowed) {
      non_allowed_categorical_var_in_input &lt;- TRUE
    }
  }

  if (non_allowed_categorical_var_in_input) {
    stop(
      "categorical_vars must only contain: ",
      paste(allowed_categorical_vars, collapse = ", ")
    )
  }

  if (numb_categorial_variables == 0) {
    stop(
      "at least one valid categorical must be specified in the input. categorical_vars must only contain: ",
      paste(allowed_categorical_vars, collapse = ", ")
    )
  }

  #let's validate geography

  variables_metadata &lt;- get_variables_by_year(year_str)

  geography_level &lt;- match_allowed_value(geography_level, c("Region", "Division", "State"))
  if (is.na(geography_level)) {
    stop("geography_level must be one of: Region, Division, State")
  }

  if (geography_level == "State") {
    if (year_str == "2021" || year_str == "2022") {
      geography_var_name &lt;- "ST"
    } else {
      geography_var_name &lt;- "STATE"
    }
    geography_for_key &lt;- "state"
  } else if (geography_level == "Division") {
    geography_var_name &lt;- "DIVISION"
    geography_for_key &lt;- "division"
  } else if (geography_level == "Region") {
    geography_var_name &lt;- "REGION"
    geography_for_key &lt;- "region"
  }


  allowed_geography_values &lt;- names(variables_supported[[geography_var_name]]$values$item)

  geography_value &lt;- match_allowed_value(geography_value, c(allowed_geography_values, "all"))
  if (is.na(geography_value)) {
    stop(
      "geography_value must be 'all' or one of the following valid values for ",
      geography_level,
      ": ",
      paste(allowed_geography_values, collapse = ", ")
    )
  }


  geography_clause &lt;- if (geography_value == "all") {
    paste0("&for=", geography_for_key, ":*")
  } else {
    paste0("&for=", geography_for_key, ":", geography_value)
  }

  url &lt;- paste0(
    "https://api.census.gov/data/",
    year_str,
    "/acs/acs1/pums?get=",
    paste(numeric_vars, collapse = ","),
    ",",
    paste(categorical_vars, collapse = ","),
    ",",
    geography_var_name,
    geography_clause,
    "&key=",# &SCHL=24 is now removed
    api_key
  )
  pums_data &lt;- GET(url)
  resp_json &lt;- fromJSON(rawToChar(pums_data$content))

  pums_tibble &lt;- as_tibble(resp_json[-1, , drop = FALSE]) # without -1 header becomes the first row
  colnames(pums_tibble) &lt;- resp_json[1, ]

  for (col_name in colnames(pums_tibble)) {
    if (col_name %in% c("JWAP", "JWDP")) {
      pums_tibble[[col_name]] &lt;- convert_time_codes_to_midpoints(pums_tibble[[col_name]], variables_supported[[col_name]])
    } else if (col_name %in% allowed_numeric_vars) {
      pums_tibble[[col_name]] &lt;- as.numeric(pums_tibble[[col_name]])
    } else if (col_name %in% allowed_categorical_vars) {
      # adding factors for all categorical values based on distinct values that they support
      pums_tibble[[col_name]] &lt;- factor(pums_tibble[[col_name]],
                                        levels = names(variables_supported[[col_name]]$values$item))
      levels(pums_tibble[[col_name]]) &lt;- unname(unlist(variables_supported[[col_name]]$values$item)) # labels

    }
  }

  class(pums_tibble) &lt;- c("census", class(pums_tibble))
  pums_tibble
}

